using System.IO;
using MPBlocks.Core;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace MPBlocks.Editor
{
    /// <summary>
    /// One dialog that turns "I want to start a game" into a playable, buildable scene.
    ///
    /// The window only chooses the name, the starting template and the session numbers;
    /// the actual scene is generated by the template builders, so no student (and no AI)
    /// ever has to hand-edit scene YAML. Creating a scene also puts it first in Build
    /// Settings and disables the Bootstrap template, so tools/build.sh builds the game
    /// instead of the demo.
    /// </summary>
    public sealed class NewGameSceneWindow : EditorWindow
    {
        public enum TemplateChoice
        {
            /// <summary>Four infrastructure objects + ground + light. Nothing else.</summary>
            Empty = 0,

            /// <summary>Players coexist and toggle world objects (Easy).</summary>
            WorldInteraction = 1,

            /// <summary>Two players must cooperate to open a door and finish a target (Medium).</summary>
            CoopMission = 2,

            /// <summary>Shooting deathmatch with respawns and a kill scoreboard (Hard).</summary>
            ArenaCombat = 3,
        }

        private string _gameName = "MyGame";
        private TemplateChoice _template = TemplateChoice.WorldInteraction;
        private MPPlayerMovement _playerMovement = MPPlayerMovement.Transform;
        private int _maxPlayers = 4;
        private int _port = 7777;
        private bool _openAfterCreate = true;

        private string _gameId = "mygame";
        private string _lastSafeName;

        [MenuItem("MPBlocks/New Game Scene...")]
        public static void Open()
        {
            var window = GetWindow<NewGameSceneWindow>(true, "New Multiplayer Game", true);
            window.minSize = new Vector2(460f, 300f);
            window.Show();
        }

        private void OnEnable()
        {
            _lastSafeName = SceneKit.SafeFileName(_gameName);
            _gameId = SceneKit.NewGameId(_lastSafeName);
        }

        private void OnGUI()
        {
            EditorGUILayout.Space(6f);
            EditorGUILayout.LabelField("Create a new multiplayer game scene", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "The scene is generated from C# (never hand-edited). It is also put first in\n" +
                "Build Settings and the Bootstrap template scene is disabled, so\n" +
                "./tools/build.sh ships this game.",
                MessageType.None);

            EditorGUILayout.Space(4f);
            _gameName = EditorGUILayout.TextField(
                new GUIContent("Game name",
                    "Used for both the scene and its NetConfig asset: Assets/Scenes/<name>.unity and " +
                    "Assets/Settings/NetConfig_<name>.asset. Letters/digits/_/- only; spaces become _."),
                _gameName);

            var safeName = SceneKit.SafeFileName(_gameName);
            if (safeName != _lastSafeName)
            {
                _lastSafeName = safeName;
                _gameId = SceneKit.NewGameId(safeName);
            }

            _template = (TemplateChoice)EditorGUILayout.EnumPopup(
                new GUIContent("Starting template",
                    "Where to start: Empty = infrastructure only; Template 1 = world interaction " +
                    "(coexist + toggle pads); Template 2 = co-op mission (levers + door); " +
                    "Template 3 = arena combat (bullets, respawn, kill score)."),
                _template);

            if (_template == TemplateChoice.ArenaCombat && _playerMovement == MPPlayerMovement.Rigidbody)
            {
                _playerMovement = MPPlayerMovement.Transform;
            }

            using (new EditorGUI.DisabledScope(_template == TemplateChoice.ArenaCombat))
            {
                _playerMovement = (MPPlayerMovement)EditorGUILayout.EnumPopup(
                    new GUIContent("Player movement",
                        "Transform = SimplePlayerMover (no gravity/physics); " +
                        "Rigidbody = RigidbodyPlayerMover (gravity, jump, collisions, owner-simulated). " +
                        "Both prefabs are generated; you can change this later on the NetConfig asset. " +
                        "Template 3 uses its own combat prefab, so it stays on Transform."),
                    _playerMovement);
            }

            _maxPlayers = EditorGUILayout.IntSlider(
                new GUIContent("Max players",
                    "Simultaneous players including the host. Written to NetConfig.maxPlayers; " +
                    "players beyond the number of PlayerSpawnPoints reuse spawn points round-robin."),
                _maxPlayers, 2, 8);
            _port = EditorGUILayout.IntField(
                new GUIContent("UDP port",
                    "LAN port, default 7777. Two games on the same LAN or machine must use different " +
                    "ports, otherwise clients connect to the wrong session."),
                _port);
            _openAfterCreate = EditorGUILayout.Toggle(
                new GUIContent("Open after creating",
                    "Open the freshly generated scene so you can edit it immediately."),
                _openAfterCreate);

            _port = Mathf.Clamp(_port, 1024, 65535);

            var spec = BuildSpec(safeName);
            EditorGUILayout.Space(6f);
            EditorGUILayout.HelpBox(
                "Scene:     " + spec.ScenePath + "\n" +
                "NetConfig: " + spec.ConfigPath + "\n" +
                "Session id: " + spec.GameId,
                MessageType.Info);

            EditorGUILayout.Space(4f);
            using (new EditorGUI.DisabledScope(string.IsNullOrWhiteSpace(_gameName)))
            {
                if (GUILayout.Button("Create scene", GUILayout.Height(32f)))
                {
                    Create(spec);
                }
            }
        }

        private GameSpec BuildSpec(string safeName)
        {
            var name = string.IsNullOrEmpty(safeName) ? "Game" : safeName;
            return new GameSpec(
                name,
                _gameId,
                _maxPlayers,
                (ushort)_port,
                SceneKit.GameScenePath(name),
                SceneKit.GameConfigPath(name));
        }

        private void Create(GameSpec spec)
        {
            if (File.Exists(spec.ScenePath) &&
                !EditorUtility.DisplayDialog("Scene already exists",
                    spec.ScenePath + " already exists.\n\nOverwrite it with a freshly generated scene?",
                    "Overwrite", "Cancel"))
            {
                return;
            }

            try
            {
                // NewScene() replaces whatever is open; never silently drop unsaved work.
                if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()) return;

                SceneKit.EnsureProjectScaffolding();

                switch (_template)
                {
                    case TemplateChoice.Empty:
                        TemplateSetup.BuildEmptyScene(spec);
                        break;
                    case TemplateChoice.WorldInteraction:
                        Template1Builder.Build(spec);
                        break;
                    case TemplateChoice.CoopMission:
                        Template2Builder.Build(spec);
                        break;
                    case TemplateChoice.ArenaCombat:
                        Template3Builder.Build(spec);
                        break;
                    default:
                        throw new System.ArgumentOutOfRangeException(nameof(_template));
                }

                // The generated config points at both player prefabs; select which one
                // the session spawns. Template 3 keeps its own combat prefab (Transform).
                var config = AssetDatabase.LoadAssetAtPath<NetConfig>(spec.ConfigPath);
                if (config != null)
                {
                    var movement = _template == TemplateChoice.ArenaCombat
                        ? MPPlayerMovement.Transform
                        : _playerMovement;

                    config.SetPlayerMovement(movement);
                    EditorUtility.SetDirty(config);
                    AssetDatabase.SaveAssets();

                    Debug.Log("[MP] INFO NEW_GAME_PLAYER_MOVEMENT name=" + spec.Name + " movement=" + movement);
                }

                // Registered as the only enabled scene: build.sh builds it, validate.sh
                // validates it, and the Bootstrap template stays on disk but disabled.
                SceneKit.RegisterScene(spec.ScenePath, true);
                SceneKit.MakeGameSceneFirst(spec.ScenePath);
                AssetDatabase.SaveAssets();
                AssetDatabase.Refresh();

                Debug.Log("[MP] INFO NEW_GAME_SCENE_CREATED name=" + spec.Name +
                          " template=" + _template + " path=" + spec.ScenePath + " gameId=" + spec.GameId);

                // Opening a scene in the middle of an OnGUI pass is fragile; let the
                // window close first, then open the freshly generated scene.
                if (_openAfterCreate)
                {
                    var scenePath = spec.ScenePath;
                    EditorApplication.delayCall += () => SceneKit.OpenScene(scenePath);
                }

                Close();
            }
            catch (System.Exception e)
            {
                Debug.LogError("[MP] ERROR NEW_GAME_SCENE_FAILED name=" + spec.Name + " reason=" + e.Message + "\n" + e);
                EditorUtility.DisplayDialog("Creating the scene failed",
                    "See the Console for details.\n\n" + e.Message, "OK");
            }
        }
    }
}
